"""Line diff and statistics."""
from collections import namedtuple

Hunk = namedtuple("Hunk", "start removed added")


def lines(text):
    parts = text.split("\n")
    if parts and parts[-1] == "":
        parts.pop()
    return parts


def unlines(items):
    return "".join(line + "\n" for line in items)


def diff(old, new):
    n, m = len(old), len(new)
    lcs = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if old[i] == new[j]:
                lcs[i][j] = lcs[i + 1][j + 1] + 1
            else:
                lcs[i][j] = max(lcs[i + 1][j], lcs[i][j + 1])
    hunks = []
    cur = None
    i = j = 0
    while i < n or j < m:
        if i < n and j < m and old[i] == new[j]:
            if cur is not None:
                hunks.append(Hunk(cur[0], tuple(cur[1]), tuple(cur[2])))
                cur = None
            i += 1
            j += 1
            continue
        if cur is None:
            cur = [i + 1, [], []]
        if j >= m or (i < n and lcs[i + 1][j] >= lcs[i][j + 1]):
            cur[1].append(old[i])
            i += 1
        else:
            cur[2].append(new[j])
            j += 1
    if cur is not None:
        hunks.append(Hunk(cur[0], tuple(cur[1]), tuple(cur[2])))
    return hunks


def stats(hunks):
    return (sum(len(h.added) for h in hunks), sum(len(h.removed) for h in hunks))

